// 弹型定义按任务要求从 transcribe/th15/touhou-bullets.ecl 复制。
// 本卡只用到源 type 5（TH15_BALL2，行基址 352 + 5*16 = 432，基础半径 4）。
const TH15_BALL2: int = 432;

// th15_s6_b10 · TH15 Stage 6 BossCard6 「溢れ出る瑕穢」/「地上穢の純化」
// source: st06bs.ecl.txt Boss6:631-672（入口/160帧准备）
//         BossCard6:1689-1764（timerReset、1800窗口、环/自机狙循环）
//         BossCard6_at:1766-1791 / BossCard6_ath:1793-1819（普通弹EX链）
// 源/目标对应写在相关语句旁。

const TIME_LIMIT: int = 2084;     // 120开场 + 160前置等待 + 4准备 + 1800源窗口
const OPENING_BUFFER: int = 120;  // 独立外壳开场缓冲
const PRE_SPELL_WAIT: int = 160;  // Boss6:669 wait(160)：Boss6 → BossCard6
const SPELL_SETUP: int = 4;       // BossCard6:1701 //4：timerReset/setInterrupt/movePosTime
const MOVE_FRAMES: int = 60;      // BossCard6:1733 movePosTime(60,4,0,192)
const WAVE_DELAY: int = 94;       // BossCard6:1740 //94：首波在BossCard6 t=94
const SPELL_FRAMES: int = 1800;   // BossCard6:1705 timerReset / :1724 setInterrupt(…,1800)
const SPELL_ID: int = 98;         // BossCard6:1726-1730 spell(98,1800,500000,…)
const COLOR_A: int = 2;           // BossCard6_at  etSprite(0,5,2)
const COLOR_B: int = 6;           // BossCard6_ath etSprite(0,5,6)

// BossCard6_at 的效果链（每条 async=0，按记录顺序）：
//   ANIM a=1        → 出生阶段整体省略；进入时 position -= 4*velocity（初速1.5 → 退6px）
//   OFFSCREEN 200,0 → offscreen_keep(200)
//   STEP a=60,b=1,c=1,s=0,r=0 → 60帧线性减速到0；段界 c=1 重新朝自机，供后续ACCEL使用
//   ACCEL a=120,r=0.02,s=-999999 → 沿当前角（保留角）加速120帧
// etDist(48) 与 ANIM 退位移同沿弹角，净出生距离 48-6=42px。
xformdef AT_XF {
    offscreen_keep(200);
    step_speed(0fx, 60);
    wait(60);
    aim_player(0deg);
    set_accel(0.02fx);
    wait(120);
    set_accel(0fx);
}

// BossCard6_ath（仅Lunatic）：记录顺序为 ANIM → OFFSCREEN → WAIT 30 → STEP → ACCEL。
xformdef ATH_XF {
    offscreen_keep(200);
    wait(30);
    step_speed(0fx, 60);
    wait(60);
    aim_player(0deg);
    set_accel(0.04fx);
    wait(120);
    set_accel(0fx);
}

async sub source_boss() {
    // 入口状态：Boss() st06bs.ecl.txt:8-34 的公共框/位置；HP取Boss6:633 lifeSet(6000)。
    set_invuln(65535);   // 训练外壳无敌；源Boss6:634 setInvuln(180)不参与DPS
    set_hitbox(25fx);    // Boss(): setHitbox(50,50) → 圆半径 50*0.5
    set_hurtbox(28fx);   // Boss(): setHurtbox(56,56) → 圆半径 56*0.5

    wait(PRE_SPELL_WAIT);                 // Boss6:669，源仍在(0,128)
    // BossCard6:1692 flagSet(3)，其中0x2为禁体碰；本卡结束改走Boss7:676 flagClear(3)。
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(SPELL_SETUP);                    // BossCard6 //4：timerReset与setInterrupt基点
    // Boss6:646 moveLimit(0,128,280,96) 在BossCard6:1734紧接非阻塞movePosTime后reset；
    // 本段唯一移动发生在reset之后，故无需常驻限位。
    move_to(MOVE_FRAMES, 0fx, 192fx, EASE_QUAD_OUT); // BossCard6:1733 movePosTime(60,4,0,192)
    wait(WAVE_DELAY - SPELL_SETUP);       // 首波在BossCard6 t=94（//94）

    var rank: int = global(GVAR_RANK);
    var at_n: int = 22;                   // !LO（N/L）
    if rank == RANK_EASY { at_n = 10; }   // !E
    if rank == RANK_HARD { at_n = 26; }   // !H
    var elapsed: int = 0;

    // 源循环：%F1=%RANDRAD → at() → ath()(!L) → $A=_S(%B) → wait($A)。
    // %B由floatTime(0,%B,1800,0,120,50)线性推进，故间隔=120-70*t/1800。
    while elapsed < SPELL_FRAMES - WAVE_DELAY {
        // BossCard6:1749 每波抽一次，Lunatic的at/ath共享。
        var base: angle = rand(65536) as angle;

        // BossCard6_at：固定方向整周环（etAim 3），路数按at_n。
        sh_reset(0);
        sh_sprite(0, TH15_BALL2, COLOR_A);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, at_n, 1);
        sh_angle(0, base, 0deg);
        sh_speed(0, 1.5fx, 0fx);          // etSpeed(0,1.5,0.2)，单层只取s0
        sh_offset_abs(0, $player_x, $player_y); // etOffsetAbs(PLAYER_X2,PLAYER_Y2)
        sh_dist(0, 42fx);                 // etDist(48) + ANIM退位移-6
        sh_xform(0, AT_XF);
        sh_fire(0);

        if rank == RANK_LUNATIC {
            // BossCard6_ath：仅Lunatic，count=11，色6，WAIT30+ACCEL 0.04。
            sh_reset(1);
            sh_sprite(1, TH15_BALL2, COLOR_B);
            sh_ring(1, 1);
            sh_aim(1, 0);
            sh_count(1, 11, 1);
            sh_angle(1, base, 0deg);
            sh_speed(1, 1.5fx, 0fx);
            sh_offset_abs(1, $player_x, $player_y);
            sh_dist(1, 42fx);
            sh_xform(1, ATH_XF);
            sh_fire(1);
        }

        var interval: int = 120 - (70 * elapsed) / SPELL_FRAMES;
        wait(interval);
        elapsed = elapsed + interval;
    }
    // 源窗口在BossCard6 t=1800结束并切Boss7；本段敌自然退场。
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Boss() 初始位置 movePos(0,128)；HP=6000。
    _ = spawn_enemy(0fx, 128fx, 6000, 0, 0, 0, source_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
